xql_query:
// ============================================================
// Rule: WIN_GPO Was Modified
// Vendor: Windows
// Objective:
// Detect activity associated with WIN_GPO Was Modified.
// Severity: SEV_040_HIGH
// Category: INFILTRATION
// ============================================================
// MITRE ATT&CK:
// Tactic: TA0005 - Defense Evasion
// Technique: T1484.001 - Domain Policy Modification: Group Policy Modification
// Technique: T1484 - Domain Policy Modification

// O preset de eventos do Windows é utilizado para analisar logs de segurança
preset = xdr_event_log  

// São considerados apenas os eventos 5136 (modificação de objeto no AD) e 5141 (exclusão de objeto no AD)
| filter action_evtlog_event_id in (5136, 5141)  

// A análise é restrita a objetos do tipo "groupPolicyContainer",
// ou seja, eventos relacionados a alterações ou exclusões de Diretivas de Grupo (GPOs)
| filter action_evtlog_data_fields -> ObjectClass = "groupPolicyContainer"  

// Novos campos são criados para facilitar a interpretação dos resultados
| alter
    timestamp = _time,                                         // Momento em que o evento ocorreu
    actor = actor_effective_username,                          // Usuário efetivo associado ao evento
    ObjectDN = action_evtlog_data_fields -> ObjectDN,          // Distinguished Name do objeto de GPO
    AttributeModified = action_evtlog_data_fields -> AttributeLDAPDisplayName, // Atributo alterado
    OperationType = action_evtlog_data_fields -> OperationType, // Tipo de operação realizada
    SubjectUserName = action_evtlog_data_fields -> SubjectUserName, // Usuário responsável pela ação
    AttributeValue = action_evtlog_data_fields -> AttributeValue   // Novo valor do atributo modificado

// Um join é realizado com o inventário do AD (pan_dss_raw) para enriquecer os dados,
// permitindo correlacionar o SubjectUserName com o display_name do executor
| join conflict_strategy=both type=left (
    dataset=pan_dss_raw 
    | fields display_name as executor, sam_account_name
) as whitelist 
whitelist.sam_account_name = SubjectUserName  

// São exibidos os campos mais relevantes para a investigação
| fields timestamp, action_evtlog_data_fields, AttributeValue, agent_hostname, agent_ip_addresses, actor, SubjectUserName, executor, ObjectDN, AttributeModified, OperationType
